    const app = createApp({ dataDir, port: 8080 });
    await request(app)
      .put("/blobs/existing.txt")
      .set("Content-Type", "application/octet-stream")
      .send(Buffer.from("already here"));

    const bigPut = request(app)
      .put("/blobs/big.bin")
      .set("Content-Type", "application/octet-stream")
