      res.on('end', () => resolve({ status: res.statusCode, payload }));
    });
    req.on('error', reject);
    req.end(payload);
  });
}

(async () => {
  const results = await Promise.all(Array.from({length: 8}, (_, i) => put(i)));
  console.log('statuses:', results.map(r => r.status));

