    http.get('http://127.0.0.1:18080/blobs/race.bin', (res) => {
      let chunks = [];
      res.on('data', c => chunks.push(c));
      res.on('end', () => resolve(Buffer.concat(chunks)));
    }).on('error', reject);
  });

  console.log('final length:', final.length);
  const matches = results.map(r => r.payload).filter(p => p.equals(final)).length;
  console.log('matches exactly one payload:', matches === 1);
})();
